Red-Black Tree Implementation

A complete Python implementation of a red-black tree with insert, delete, and search operations, including a comprehensive test suite.

Red-Black Tree Properties

Every node is either red or black

The root is black

Every leaf (NIL) is black

If a node is red, both its children are black

For each node, all simple paths from the node to descendant leaves contain the same number of black nodes

Implementation

```python
class Node:
    """A node in a Red-Black Tree."""

    def __init__(self, key, color="RED", left=None, right=None, parent=None):
        """Initialize a node with a key and color."""
        self.key = key
        self.color = color
        self.left = left
        self.right = right
        self.parent = parent

    def __repr__(self):
        return f"Node({self.key}, {self.color})"


class RedBlackTree:
    """A Red-Black Tree implementation supporting insert, delete, and search."""

    def __init__(self):
        """Initialize an empty Red-Black Tree with a sentinel NIL node."""
        self.NIL = Node(key=None, color="BLACK")
        self.root = self.NIL
        self.size = 0

    # ---------- Search Operations ----------

    def search(self, key):
        """Search for a key in the tree. Returns the node or None."""
        node = self.root
        while node != self.NIL:
            if key == node.key:
                return node
            elif key < node.key:
                node = node.left
            else:
                node = node.right
        return None

    def __contains__(self, key):
        """Support the 'in' operator."""
        return self.search(key) is not None

    def minimum(self, node=None):
        """Find the node with the minimum key in the subtree."""
        if node is None:
            node = self.root
        if node == self.NIL:
            return None
        while node.left != self.NIL:
            node = node.left
        return node

    def maximum(self, node=None):
        """Find the node with the maximum key in the subtree."""
        if node is None:
            node = self.root
        if node == self.NIL:
            return None
        while node.right != self.NIL:
            node = node.right
        return node

